&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 data-start=&quot;951&quot; data-end=&quot;968&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong data-start=&quot;958&quot; data-end=&quot;968&quot;&gt;Астана&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;ul data-start=&quot;970&quot; data-end=&quot;1130&quot;&gt;
